#!/usr/bin/env bash
# Crea etiquetas e issues de la hoja de ruta en GitHub. Requiere: gh auth login
# Uso: ./scripts/crear-issues.sh RduranPRT/compas
set -euo pipefail
R="${1:?indica owner/repo}"

for l in "spec:0e8a16" "marcha-blanca:fbca04" "error:d73a4a" "adr:5319e7" "decision:c5def5" "ola-1:bfdadc" "ola-2:bfdadc" "ola-3:bfdadc" "ola-4:bfdadc"; do
  gh label create "${l%%:*}" --color "${l##*:}" -R "$R" --force >/dev/null
done

gh issue create -R "$R" --label adr,decision --title "Aprobar ADR 01 a 09" --body "Revisa docs/adr/README.md. Para cada ADR de acuerdo, comenta: @claude marca como Aceptada la ADR-0X. Si quieres cambiar algo, explícalo y pide a Claude que actualice la ADR."
gh issue create -R "$R" --label decision --title "Preguntas abiertas de las specs 001 a 004" --body "$(printf '%b' "- Spec 001: ¿los hijos tienen correo propio o se usan alias? ¿cuántos y sus nombres para la mesada?
- Spec 002/003: bancos, tarjetas y formato de cartola de cada uno.
- Spec 004: ¿hay ahorros fuera de las cuentas registradas?

Responde aquí y comenta @claude actualiza las specs con estas respuestas.")"

gh issue create -R "$R" --label spec,ola-1 --title "Spec 001 · Base de la plataforma, hogar y acceso" --body "$(printf '%b' "**13–18 oct** · `specs/001-base-plataforma/spec.md`\n\nEstado: borrador · Fecha: 2026-10-12 · Épica: EP01, EP14\n\nQue la familia pueda instalar la app, iniciar sesión, crear el hogar con sus integrantes y dejar firmado el Acuerdo del Hogar v1 con el inicio del piloto, sobre una base de datos segura donde cada hogar ve solo lo suyo.\n\n**Ciclo:** aprobar la spec → @claude /implementar 001 → @claude /verificar 001")"
gh issue create -R "$R" --label spec,ola-1 --title "Spec 002 · Cuentas, tarjetas, categorías y sobres del período" --body "$(printf '%b' "**13–18 oct** · `specs/002-cuentas-categorias/spec.md`\n\nEstado: borrador · Fecha: 2026-10-12 · Épica: EP02, EP03\n\nDejar registradas las cuentas y tarjetas del hogar con su saldo al 1 de octubre, las categorías del hogar y los sobres de cada período, para que los movimientos importados o capturados tengan dónde caer.\n\n**Ciclo:** aprobar la spec → @claude /planificar 002 → @claude /tareas 002 → @claude /implementar 002 → @claude /verificar 002")"
gh issue create -R "$R" --label spec,ola-2 --title "Spec 003 · Importación de cartolas y estados de cuenta" --body "$(printf '%b' "**19–30 oct** · `specs/003-importacion-cartolas/spec.md`\n\nEstado: borrador · Fecha: 2026-10-12 · Épica: EP16 (nueva)\n\nCargar en minutos los movimientos reales del hogar desde los documentos del banco: los anteriores al 1 de octubre alimentan el perfil inicial y los posteriores quedan como movimientos del piloto, listos para confirmar. Es la base de la línea base de octubre y noviembre.\n\n**Ciclo:** aprobar la spec → @claude /planificar 003 → @claude /tareas 003 → @claude /implementar 003 → @claude /verificar 003")"
gh issue create -R "$R" --label spec,ola-2 --title "Spec 004 · Perfil inicial y retroalimentación" --body "$(printf '%b' "**19–30 oct** · `specs/004-perfil-inicial/spec.md`\n\nEstado: borrador · Fecha: 2026-10-12 · Épica: EP16 (nueva)\n\nQue el hogar vea, en una pantalla, cómo ha manejado su dinero los últimos meses y reciba de 3 a 5 hallazgos concretos con su regla, para tomar decisiones informadas en el primer plan y confirmar su etapa.\n\n**Ciclo:** aprobar la spec → @claude /planificar 004 → @claude /tareas 004 → @claude /implementar 004 → @claude /verificar 004")"
gh issue create -R "$R" --label spec,ola-2 --title "Spec 005 · Captura y clasificación de movimientos" --body "$(printf '%b' "**19–30 oct** · `specs/005-captura-movimientos/spec.md`\n\nEstado: borrador · Fecha: 2026-10-12 · Épica: EP06\n\nRegistrar cada gasto en menos de 10 segundos, por formulario o por chat, con la intención inferida, y dejar que el CAD confirme por excepción. Con esta spec la app entra en marcha blanca.\n\n**Ciclo:** aprobar la spec → @claude /planificar 005 → @claude /tareas 005 → @claude /implementar 005 → @claude /verificar 005")"
gh issue create -R "$R" --label spec,ola-3 --title "Spec 006 · Plan mensual base cero" --body "$(printf '%b' "**2–20 nov** · `specs/006-plan-mensual/spec.md`\n\nEstado: borrador · Fecha: 2026-10-12 · Épica: EP04\n\nQue el día 25 los administradores reciban un borrador de presupuesto base cero para el mes siguiente, armado con el perfil y la historia, lo ajusten y lo aprueben antes del día 1. El primero es el de diciembre de 2026.\n\n**Ciclo:** aprobar la spec → @claude /planificar 006 → @claude /tareas 006 → @claude /implementar 006 → @claude /verificar 006")"
gh issue create -R "$R" --label spec,ola-3 --title "Spec 007 · Ingresos y distribución del día de pago" --body "$(printf '%b' "**2–20 nov** · `specs/007-ingresos-distribucion/spec.md`\n\nEstado: borrador · Fecha: 2026-10-12 · Épica: EP05\n\nCuando llega un sueldo o un bono, repartirlo en minutos según el plan y la etapa, y dejar la lista de transferencias que el hogar hace en su banco (la app no mueve dinero).\n\n**Ciclo:** aprobar la spec → @claude /planificar 007 → @claude /tareas 007 → @claude /implementar 007 → @claude /verificar 007")"
gh issue create -R "$R" --label spec,ola-3 --title "Spec 008 · Ciclo de la tarjeta de crédito" --body "$(printf '%b' "**2–20 nov** · `specs/008-tarjeta-credito/spec.md`\n\nEstado: borrador · Fecha: 2026-10-12 · Épica: EP02, EP07\n\nComo la tarjeta es el medio de pago principal, que el hogar sepa en todo momento cuánto debe pagar a fin de mes y que ese dinero ya esté apartado: cada compra con tarjeta sale de su categoría y queda reservada para pagar la tarjeta.\n\n**Ciclo:** aprobar la spec → @claude /planificar 008 → @claude /tareas 008 → @claude /implementar 008 → @claude /verificar 008")"
gh issue create -R "$R" --label spec,ola-4 --title "Spec 009 · Control, alertas y reasignación N1" --body "$(printf '%b' "**21–30 nov** · `specs/009-control-alertas/spec.md`\n\nEstado: borrador · Fecha: 2026-10-12 · Épica: EP08, EP09\n\nAvisar a tiempo y sin culpa cuando un sobre va rápido o queda negativo, y permitir corregirlo moviendo dinero entre sobres en dos toques.\n\n**Ciclo:** aprobar la spec → @claude /planificar 009 → @claude /tareas 009 → @claude /implementar 009 → @claude /verificar 009")"
gh issue create -R "$R" --label spec,ola-4 --title "Spec 010 · Cierres semanal y mensual, KPI y línea base" --body "$(printf '%b' "**21–30 nov** · `specs/010-cierres-kpi/spec.md`\n\nEstado: borrador · Fecha: 2026-10-12 · Épica: EP10, EP12\n\nCerrar cada semana en 15 minutos y cada mes en 45, con las cuentas cuadradas, la valoración de la familia y los indicadores calculados. Los cierres de octubre y noviembre establecen la línea base.\n\n**Ciclo:** aprobar la spec → @claude /planificar 010 → @claude /tareas 010 → @claude /implementar 010 → @claude /verificar 010")"
gh issue create -R "$R" --label spec,ola-4 --title "Spec 011 · Privacidad, derechos y retención (Ley 21.719)" --body "$(printf '%b' "**21–30 nov** · `specs/011-privacidad-derechos/spec.md`\n\nEstado: borrador · Fecha: 2026-10-12 · Épica: EP14\n\nLlegar al 1 de diciembre de 2026, fecha de entrada en vigencia de la Ley 21.719, con consentimientos por finalidad, ejercicio de derechos y retención de datos funcionando, aunque el producto sea solo para el hogar.\n\n**Ciclo:** aprobar la spec → @claude /planificar 011 → @claude /tareas 011 → @claude /implementar 011 → @claude /verificar 011")"
echo "Issues creados."
